-- V1: separate Assessment 3 database. Never modifies Assessment 2 records.
CREATE TABLE IF NOT EXISTS schema_version(version INT PRIMARY KEY);
MERGE INTO schema_version KEY(version) VALUES(1);
CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(80) UNIQUE NOT NULL, display_name VARCHAR(120) NOT NULL, password_hash VARCHAR(400) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('coordinator','worker')));
CREATE TABLE IF NOT EXISTS sessions (token_hash VARCHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS projects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(80) NOT NULL, name_key VARCHAR(160) UNIQUE NOT NULL, description VARCHAR(1000) NOT NULL DEFAULT '', created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS tasks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title VARCHAR(120) NOT NULL, description VARCHAR(1000) NOT NULL DEFAULT '', status VARCHAR(20) NOT NULL CHECK(status IN ('todo','in_progress','submitted','done')), assigned_to BIGINT REFERENCES users(id), completion_note VARCHAR(1000) NOT NULL DEFAULT '', latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, version BIGINT NOT NULL DEFAULT 0, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_tasks_project ON tasks(project_id);
CREATE TABLE IF NOT EXISTS event_outbox (event_id VARCHAR(64) PRIMARY KEY, payload CLOB NOT NULL, published BOOLEAN NOT NULL DEFAULT FALSE, created_at VARCHAR(40) NOT NULL);
